      "Accord très fort : LFI place l’extension des droits et libertés, l’égalité et la lutte contre les discriminations au cœur de son programme, avec une conception large des libertés civiles. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Accord fort : des députés LFI ont déposé une proposition de loi visant explicitement à mettre fin aux EHPAD privés à but lucratif et à privilégier les établissements publics ou privés non lucratifs. La proposition correspond presque exactement au principe posé par la question.",
      "Accord net : LFI défend l’extension des services publics et de la protection sociale, un accès plus égalitaire à la santé, à l’école et au logement, ainsi qu’un encadrement accru des acteurs privés dans les secteurs essentiels. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Désaccord très fort : LFI place l’extension des droits et libertés, l’égalité et la lutte contre les discriminations au cœur de son programme, avec une conception large des libertés civiles. La position est directement ou presque entièrement opposée au sens de l’affirmation.",
      "Accord modéré : LFI défend l’extension des services publics et de la protection sociale, un accès plus égalitaire à la santé, à l’école et au logement, ainsi qu’un encadrement accru des acteurs privés dans les secteurs essentiels. Elle donne une orientation favorable, mais plus limitée, conditionnelle ou moins explicite que l’affirmation complète."
