      "Désaccord très fort : Le PCF défend une forte hausse des salaires, une fiscalité beaucoup plus progressive, le rétablissement et le renforcement de l’impôt sur la fortune et une contribution accrue du capital au financement collectif. La position est directement ou presque entièrement opposée au sens de l’affirmation.",
