      "Accord très fort : Le PCF veut renforcer la propriété et la maîtrise publiques dans les secteurs stratégiques, développer les services publics, encadrer les entreprises et donner davantage de pouvoir aux salariés. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Désaccord très fort : Le PCF veut renforcer la propriété et la maîtrise publiques dans les secteurs stratégiques, développer les services publics, encadrer les entreprises et donner davantage de pouvoir aux salariés. La position est directement ou presque entièrement opposée au sens de l’affirmation.",
      "Accord net : Le PCF lie son projet républicain à l’égalité des droits, à la lutte contre les discriminations et à l’émancipation sociale, tout en défendant un cadre commun laïque. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Le PCF demande de ne pas recourir au 49.3 et défend sa suppression : désaccord maximal avec la proposition. Position officielle explicite.",
      "Accord modéré : Le PCF lie son projet républicain à l’égalité des droits, à la lutte contre les discriminations et à l’émancipation sociale, tout en défendant un cadre commun laïque. Elle donne une orientation favorable, mais plus limitée, conditionnelle ou moins explicite que l’affirmation complète.",
      "Accord net : Le PCF lie son projet républicain à l’égalité des droits, à la lutte contre les discriminations et à l’émancipation sociale, tout en défendant un cadre commun laïque. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Désaccord net : le PCF défend une décentralisation dotée de moyens et de compétences locales, mais reste attaché à l’égalité républicaine et à l’unicité des règles nationales dans les domaines sociaux essentiels ; il est donc réservé face à une différenciation normative large entre régions.",
