      "Désaccord très fort : Le PCF défend la régularisation des travailleurs sans papiers, l’égalité des droits et l’intégration par le travail, les services publics et l’apprentissage de la langue plutôt qu’une politique de préférence nationale. La position est directement ou presque entièrement opposée au sens de l’affirmation.",
