      "Désaccord net : Le programme 2026 des Écologistes renforce les services publics, la santé, l’école, le logement et la protection du grand âge, avec un encadrement important des opérateurs privés et des objectifs sociaux et écologiques. Ils vont nettement à l’encontre de l’affirmation, même si tous les termes de la question ne sont pas rejetés explicitement.",
      "Accord très fort : Le programme 2026 des Écologistes renforce les services publics, la santé, l’école, le logement et la protection du grand âge, avec un encadrement important des opérateurs privés et des objectifs sociaux et écologiques. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Accord très fort : Le programme 2026 des Écologistes renforce les services publics, la santé, l’école, le logement et la protection du grand âge, avec un encadrement important des opérateurs privés et des objectifs sociaux et écologiques. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Accord très fort : Les Écologistes assument explicitement une Europe fédérale, plus démocratique et plus intégrée, et souhaitent européaniser davantage plusieurs politiques économiques, climatiques et de défense. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Accord fort : en mars 2026, Les Écologistes ont explicitement soutenu l’extension de la garantie nucléaire française aux partenaires européens tout en maintenant la décision finale d’emploi entre les mains de la France. La position correspond presque exactement à la question : +3.",
      "Accord très fort : Les Écologistes placent les libertés, l’égalité des droits et la lutte contre les discriminations de genre, d’origine, de religion, de handicap ou d’orientation sexuelle au cœur de leur projet. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Accord modéré : Les Écologistes veulent développer les EHPAD publics et non lucratifs, mais ne proposent pas clairement d'interdire tous les EHPAD privés lucratifs existants ni de les convertir.",
      "Position intermédiaire : Le programme 2026 des Écologistes renforce les services publics, la santé, l’école, le logement et la protection du grand âge, avec un encadrement important des opérateurs privés et des objectifs sociaux et écologiques. Ces éléments ne tranchent pas clairement l’arbitrage précis posé par la question, ce qui justifie une position intermédiaire.",
      "Accord modéré : Les Écologistes placent les libertés, l’égalité des droits et la lutte contre les discriminations de genre, d’origine, de religion, de handicap ou d’orientation sexuelle au cœur de leur projet. Elle donne une orientation favorable, mais plus limitée, conditionnelle ou moins explicite que l’affirmation complète.",
      "Accord net : Le programme 2026 des Écologistes renforce les services publics, la santé, l’école, le logement et la protection du grand âge, avec un encadrement important des opérateurs privés et des objectifs sociaux et écologiques. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question."
