      "Réserve modérée : Le PS défend une sécurité de proximité articulant police, prévention et justice, avec des moyens publics renforcés mais sous contrôle de l’État de droit et sans faire de la seule répression le principe directeur. Ces éléments créent plutôt une réserve à l’égard de l’affirmation, sans constituer une opposition complète à tous ses termes.",
