      "Accord net : le PS défend des mesures miroir fortes et conditionne l'accès au marché au respect des normes européennes, tout en restant favorable à un commerce encadré ; l'acceptation du renchérissement alimentaire n'est pas assez explicite pour +3.",
      "Accord très fort : Le Projet socialiste 2026 veut planifier la bifurcation écologique, fixer des objectifs environnementaux opposables aux ministères et utiliser des interdictions, investissements et prises de contrôle publiques dans plusieurs secteurs. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Accord net : Le Projet socialiste 2026 veut planifier la bifurcation écologique, fixer des objectifs environnementaux opposables aux ministères et utiliser des interdictions, investissements et prises de contrôle publiques dans plusieurs secteurs. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Le PS critique le déplacement du financement vers les impôts sur la consommation et défend un financement social plus progressif. Opposition nette, mais pas une interdiction absolue du mécanisme dans toutes ses variantes.",
