      "Accord net : Renaissance reste attaché aux institutions de la Ve République et à un exécutif capable d’agir, tout en défendant l’État de droit, la représentation parlementaire et des formes de participation citoyenne. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
