      "Accord net : Renaissance reste attaché aux institutions de la Ve République et à un exécutif capable d’agir, tout en défendant l’État de droit, la représentation parlementaire et des formes de participation citoyenne. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Réserve modérée : Renaissance reste attaché aux institutions de la Ve République et à un exécutif capable d’agir, tout en défendant l’État de droit, la représentation parlementaire et des formes de participation citoyenne. Ces éléments créent plutôt une réserve à l’égard de l’affirmation, sans constituer une opposition complète à tous ses termes.",
      "Accord net : Renaissance propose de renforcer les critères de maîtrise du français pour le regroupement familial et d’utiliser la maîtrise du français parmi les critères d’une immigration par points. Le travail et l’intégration sont explicitement liés, mais la convention ne pose pas une condition générale identique pour tout séjour durable ; +2 est plus adapté que +3.",
      "Accord modéré : Renaissance propose une immigration de travail pilotée par quotas et points, avec critères de qualification, d’emploi et de français, un regroupement familial plus exigeant et des mesures contre l’immigration irrégulière. Elle donne une orientation favorable, mais plus limitée, conditionnelle ou moins explicite que l’affirmation complète.",
      "Réserve : Ensemble pour la République défend les exigences environnementales mais accepte des dérogations ciblées et temporaires pour les filières sans solution alternative lorsque la production est gravement menacée. L’interdiction maintenue malgré le désavantage concurrentiel n’est donc pas sa ligne générale.",
