      "Accord modéré : Renaissance défend des services publics modernisés et évalués, l’investissement dans l’école et la santé et une action publique davantage contractualisée, tout en laissant une place importante aux acteurs privés. Elle donne une orientation favorable, mais plus limitée, conditionnelle ou moins explicite que l’affirmation complète.",
