      "Désaccord net : Horizons défend des institutions capables de décider et de réformer, tout en se réclamant de la démocratie représentative, de l’État de droit et d’une culture politique de responsabilité. Ils vont nettement à l’encontre de l’affirmation, même si tous les termes de la question ne sont pas rejetés explicitement.",
      "Accord net : Horizons défend des institutions capables de décider et de réformer, tout en se réclamant de la démocratie représentative, de l’État de droit et d’une culture politique de responsabilité. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Réserve modérée : Horizons défend des institutions capables de décider et de réformer, tout en se réclamant de la démocratie représentative, de l’État de droit et d’une culture politique de responsabilité. Ces éléments créent plutôt une réserve à l’égard de l’affirmation, sans constituer une opposition complète à tous ses termes.",
      "Accord très fort : Horizons rejette l’idée que la France puisse accueillir sans limite et insiste sur l’intégration, la maîtrise des flux et une culture commune, sans défendre pour autant l’autarcie ou la fermeture totale. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Position intermédiaire : Horizons rejette l’idée que la France puisse accueillir sans limite et insiste sur l’intégration, la maîtrise des flux et une culture commune, sans défendre pour autant l’autarcie ou la fermeture totale. Ces éléments ne tranchent pas clairement l’arbitrage précis posé par la question, ce qui justifie une position intermédiaire.",
      "Désaccord net : Horizons soutient majoritairement le compromis agricole ouvrant des dérogations encadrées et insiste sur les moyens de production, les contraintes pesant sur les exploitants et leur capacité à vivre de leur activité. La position est toutefois moins explicite que celle de LR ou du RN sur le principe général.",
      "Accord modéré : Horizons travaille sur l’accès aux soins, l’école, l’emploi, l’énergie et les services territoriaux avec une logique de réforme et d’efficacité plutôt que de retrait général de l’action publique. Elle donne une orientation favorable, mais plus limitée, conditionnelle ou moins explicite que l’affirmation complète.",
      "Désaccord net : Horizons travaille sur l’accès aux soins, l’école, l’emploi, l’énergie et les services territoriaux avec une logique de réforme et d’efficacité plutôt que de retrait général de l’action publique. Ils vont nettement à l’encontre de l’affirmation, même si tous les termes de la question ne sont pas rejetés explicitement.",
      "Accord net : Horizons travaille sur l’accès aux soins, l’école, l’emploi, l’énergie et les services territoriaux avec une logique de réforme et d’efficacité plutôt que de retrait général de l’action publique. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Accord fort : Horizons défend une autonomie accrue des établissements scolaires et un rôle beaucoup plus important des chefs d'établissement dans le recrutement et l'évaluation des enseignants. La proposition correspond directement à cette orientation.",
      "Position intermédiaire : Horizons travaille sur l’accès aux soins, l’école, l’emploi, l’énergie et les services territoriaux avec une logique de réforme et d’efficacité plutôt que de retrait général de l’action publique. Ces éléments ne tranchent pas clairement l’arbitrage précis posé par la question, ce qui justifie une position intermédiaire.",
      "Position intermédiaire : Horizons travaille sur l’accès aux soins, l’école, l’emploi, l’énergie et les services territoriaux avec une logique de réforme et d’efficacité plutôt que de retrait général de l’action publique. Ces éléments ne tranchent pas clairement l’arbitrage précis posé par la question, ce qui justifie une position intermédiaire.",
      "Accord très fort : Horizons voit l’Europe comme un levier de prospérité et de souveraineté française, tout en demandant davantage de subsidiarité et le respect des choix fondamentaux du peuple français. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Accord très fort : Horizons voit l’Europe comme un levier de prospérité et de souveraineté française, tout en demandant davantage de subsidiarité et le respect des choix fondamentaux du peuple français. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Position intermédiaire : Horizons défend la laïcité et l’universalisme républicain, combat les assignations identitaires et rejette à la fois le multiculturalisme communautaire et les atteintes aux libertés démocratiques. Ces éléments ne tranchent pas clairement l’arbitrage précis posé par la question, ce qui justifie une position intermédiaire.",
