      "Réserve modérée : LR défend les libertés individuelles et la propriété mais insiste aussi sur la transmission d’un modèle de civilisation, la laïcité, l’autorité et la cohésion nationale. Ces éléments créent plutôt une réserve à l’égard de l’affirmation, sans constituer une opposition complète à tous ses termes.",
      "LR a explicitement défendu l’engagement de responsabilité par le 49.3 afin de doter la France d’un budget ; Bruno Retailleau a aussi critiqué l’abandon du 49.3 en période de blocage. Accord maximal.",
      "Désaccord net : LR défend les libertés individuelles et la propriété mais insiste aussi sur la transmission d’un modèle de civilisation, la laïcité, l’autorité et la cohésion nationale. Ils vont nettement à l’encontre de l’affirmation, même si tous les termes de la question ne sont pas rejetés explicitement.",
      "Réserve modérée : LR défend les libertés individuelles et la propriété mais insiste aussi sur la transmission d’un modèle de civilisation, la laïcité, l’autorité et la cohésion nationale. Ces éléments créent plutôt une réserve à l’égard de l’affirmation, sans constituer une opposition complète à tous ses termes.",
      "Accord net : LR soutient le principe de différenciation territoriale et n’est pas opposé à un pouvoir réglementaire local accru, à condition de préserver l’unité nationale et de ne pas systématiser les dérogations.",
      "Accord très fort : LR défend les libertés individuelles et la propriété mais insiste aussi sur la transmission d’un modèle de civilisation, la laïcité, l’autorité et la cohésion nationale. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Accord très fort : Bruno Retailleau veut réduire fortement l’immigration légale et illégale, réviser le cadre constitutionnel et européen et renforcer les exigences d’intégration et de maîtrise des flux. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Désaccord net : Bruno Retailleau affirme explicitement que l’immigration « n’est pas une chance pour la France, mais une charge » et rejette l’idée de recourir à davantage d’immigration pour répondre aux pénuries de main-d’œuvre, préférant former les Français et les étrangers déjà présents légalement.",
      "LR veut imposer une durée de résidence et d’activité avant l’accès à certaines aides, mais refuse une priorité au logement social fondée sur la nationalité ; la formulation visant les résidents de longue date recueille donc un accord net.",
      "Accord net : Bruno Retailleau veut réduire fortement l’immigration légale et illégale, réviser le cadre constitutionnel et européen et renforcer les exigences d’intégration et de maîtrise des flux. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Accord très fort : Bruno Retailleau veut réduire fortement l’immigration légale et illégale, réviser le cadre constitutionnel et européen et renforcer les exigences d’intégration et de maîtrise des flux. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Accord très fort : Bruno Retailleau veut réduire fortement l’immigration légale et illégale, réviser le cadre constitutionnel et européen et renforcer les exigences d’intégration et de maîtrise des flux. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Désaccord net : Bruno Retailleau veut réduire fortement l’immigration légale et illégale, réviser le cadre constitutionnel et européen et renforcer les exigences d’intégration et de maîtrise des flux. Ils vont nettement à l’encontre de l’affirmation, même si tous les termes de la question ne sont pas rejetés explicitement.",
      "Accord très fort : LR présente la sécurité comme la première des libertés et demande une autorité de l’État sans faiblesse, davantage de fermeté pénale et une politique plus restrictive face à la délinquance. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Accord modéré : LR présente la sécurité comme la première des libertés et demande une autorité de l’État sans faiblesse, davantage de fermeté pénale et une politique plus restrictive face à la délinquance. Elle donne une orientation favorable, mais plus limitée, conditionnelle ou moins explicite que l’affirmation complète.",
      "Accord net : LR présente la sécurité comme la première des libertés et demande une autorité de l’État sans faiblesse, davantage de fermeté pénale et une politique plus restrictive face à la délinquance. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Accord net : LR veut corriger la concurrence déloyale et peut soutenir des interdictions d'importation, mais propose aussi de supprimer certaines surtranspositions ou restrictions françaises lorsque celles-ci pénalisent les producteurs ; +2 est plus adapté que +3.",
      "Accord modéré : LR défend une « écologie des solutions » qui concilie environnement et développement, mise surtout sur la science, l’innovation et l’entreprise et rejette une écologie punitive ou décroissante. Elle donne une orientation favorable, mais plus limitée, conditionnelle ou moins explicite que l’affirmation complète.",
      "Réserve modérée : LR défend une « écologie des solutions » qui concilie environnement et développement, mise surtout sur la science, l’innovation et l’entreprise et rejette une écologie punitive ou décroissante. Ces éléments créent plutôt une réserve à l’égard de l’affirmation, sans constituer une opposition complète à tous ses termes.",
      "Gérard Larcher présente explicitement la TVA sociale comme une piste à examiner pour agir sur salaire net et compétitivité, sans en faire une proposition arrêtée. Faible accord : +1.",
      "Accord net : LR défend une « écologie des solutions » qui concilie environnement et développement, mise surtout sur la science, l’innovation et l’entreprise et rejette une écologie punitive ou décroissante. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Position intermédiaire : LR défend une « écologie des solutions » qui concilie environnement et développement, mise surtout sur la science, l’innovation et l’entreprise et rejette une écologie punitive ou décroissante. Ces éléments ne tranchent pas clairement l’arbitrage précis posé par la question, ce qui justifie une position intermédiaire.",
