      "Position intermédiaire : LR veut une France forte dans une Europe indépendante mais refuse que l’intégration européenne efface la souveraineté nationale ou impose des choix contraires aux intérêts français. Ces éléments ne tranchent pas clairement l’arbitrage précis posé par la question, ce qui justifie une position intermédiaire.",
      "Accord modéré : LR veut une France forte dans une Europe indépendante mais refuse que l’intégration européenne efface la souveraineté nationale ou impose des choix contraires aux intérêts français. Elle donne une orientation favorable, mais plus limitée, conditionnelle ou moins explicite que l’affirmation complète.",
