      "Accord très fort : LR veut réduire la dépense publique plutôt qu’augmenter les impôts, valoriser le travail, la propriété, l’entrepreneuriat et la compétitivité et alléger la pression fiscale sur l’activité. La position correspond directement ou presque entièrement au sens de l’affirmation.",
