      "Accord net : LR défend désormais explicitement le développement d'une part de capitalisation en complément du système par répartition ; le principe de combinaison des deux piliers correspond directement à la question.",
      "Accord modéré : LR souhaite tenir compte du vieillissement démographique et travailler plus longtemps, mais ne propose pas clairement une indexation automatique de l'âge légal sur l'espérance de vie ; +1 plutôt que +2.",
