      "Réserve modérée : Nouvelle Énergie rejette la décroissance et l’écologie punitive, veut tarifer la pollution par un prix du carbone redistribué, protéger la compétitivité et miser sur le nucléaire, la science et l’innovation. Ces éléments créent plutôt une réserve à l’égard de l’affirmation, sans constituer une opposition complète à tous ses termes.",
      "Désaccord modéré : Nouvelle Énergie critique le pouvoir technocratique et le dessaisissement des responsables élus, tout en valorisant l'expertise et l'évaluation ; -1 traduit cette réserve sans surestimer l'opposition.",
      "Accord modéré : Nouvelle Énergie défend une forte décentralisation, davantage de responsabilité locale et une démocratie plus directe, parallèlement à un État national recentré et plus efficace. Elle donne une orientation favorable, mais plus limitée, conditionnelle ou moins explicite que l’affirmation complète.",
      "Accord fort : Nouvelle Énergie veut généraliser les référendums, permettre de soumettre largement les sujets au pays et rendre effectif le référendum d'initiative citoyenne ; la correspondance avec la question est très directe.",
      "Désaccord modéré : Nouvelle Énergie défend la légitimité du suffrage universel et le recours accru au référendum, sans proposer de donner davantage de poids politique aux citoyens selon leur niveau de connaissance. -1 traduit cette réserve sans surinterpréter sa doctrine.",
      "Accord net : Nouvelle Énergie défend une forte décentralisation, davantage de responsabilité locale et une démocratie plus directe, parallèlement à un État national recentré et plus efficace. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Désaccord fort : David Lisnard et Nouvelle Énergie rejettent explicitement la proportionnelle intégrale, notamment parce qu'elle affaiblirait la capacité de l'exécutif à gouverner ; opposition directe à la question.",
      "Accord très fort : Nouvelle Énergie veut réduire fortement les titres de séjour, privilégier les profils qualifiés, renforcer les tests d’intégration et d’assimilation, limiter le droit du sol et durcir l’accès aux prestations. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Réserve modérée : Nouvelle Énergie veut réduire fortement les titres de séjour, privilégier les profils qualifiés, renforcer les tests d’intégration et d’assimilation, limiter le droit du sol et durcir l’accès aux prestations. Ces éléments créent plutôt une réserve à l’égard de l’affirmation, sans constituer une opposition complète à tous ses termes.",
      "Désaccord fort : Nouvelle Énergie veut mettre fin aux surtranspositions françaises, aligner les règles sur le marché commun et autoriser un usage raisonné des produits phytosanitaires sur base scientifique ; le programme refuse explicitement les normes qui affaiblissent la compétitivité sans bénéfice démontré.",
      "Désaccord net : le livret santé de Nouvelle Énergie privilégie la liberté d’installation et des incitations par le conventionnement ou le remboursement plutôt qu’une interdiction administrative d’installation dans les zones déjà dotées.",
      "Désaccord net : Nouvelle Énergie veut préserver les fonctions essentielles de santé et d’éducation mais les gérer avec davantage d’autonomie, de concurrence, d’évaluation et de liberté de choix. Ils vont nettement à l’encontre de l’affirmation, même si tous les termes de la question ne sont pas rejetés explicitement.",
      "Position équilibrée ou non tranchée : le programme santé insiste sur la proximité des soins, la liberté d’organisation et une gouvernance locale, mais ne tranche pas explicitement la fermeture ou le regroupement de petites maternités et de petits services d’urgence. Un accord net n’est donc pas documenté.",
      "Accord très fort : Nouvelle Énergie veut préserver les fonctions essentielles de santé et d’éducation mais les gérer avec davantage d’autonomie, de concurrence, d’évaluation et de liberté de choix. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Désaccord très fort : Nouvelle Énergie veut préserver les fonctions essentielles de santé et d’éducation mais les gérer avec davantage d’autonomie, de concurrence, d’évaluation et de liberté de choix. La position est directement ou presque entièrement opposée au sens de l’affirmation.",
      "Désaccord net : Nouvelle Énergie veut préserver les fonctions essentielles de santé et d’éducation mais les gérer avec davantage d’autonomie, de concurrence, d’évaluation et de liberté de choix. Ils vont nettement à l’encontre de l’affirmation, même si tous les termes de la question ne sont pas rejetés explicitement.",
      "Accord net : Nouvelle Énergie veut utiliser l’Europe comme levier de puissance tout en combattant son fonctionnement technocratique et en maintenant la souveraineté et l’indépendance françaises. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Accord net mais conditionnel : David Lisnard considère que l’extension de la couverture nucléaire française aux partenaires européens peut aller dans le bon sens à condition absolue que la France demeure seule décisionnaire. L’accord est clair mais assorti de fortes réserves : +2.",
      "Réserve modérée : Nouvelle Énergie place la liberté individuelle, la responsabilité, le mérite et l’universalisme républicain au centre de son projet, tout en rejetant les courants identitaires qu’elle qualifie de racialistes ou wokistes. Ces éléments créent plutôt une réserve à l’égard de l’affirmation, sans constituer une opposition complète à tous ses termes.",
      "Désaccord très fort : Nouvelle Énergie veut préserver les fonctions essentielles de santé et d’éducation mais les gérer avec davantage d’autonomie, de concurrence, d’évaluation et de liberté de choix. La position est directement ou presque entièrement opposée au sens de l’affirmation.",
      "Accord net : Nouvelle Énergie veut préserver les fonctions essentielles de santé et d’éducation mais les gérer avec davantage d’autonomie, de concurrence, d’évaluation et de liberté de choix. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Désaccord fort : Nouvelle Énergie qualifie l’interdiction des réseaux sociaux aux moins de 15 ans d’aveu d’impuissance publique et lui préfère la responsabilisation des plateformes et une régulation de leurs modèles addictifs.",
      "Accord modéré : Nouvelle Énergie défend une souveraineté technologique française et européenne dans l’IA, les données et les infrastructures critiques ; le parti ne dit toutefois pas qu’il faudrait systématiquement accepter des modèles moins performants ou plus coûteux."
