      "Accord modéré : l’UDR veut simplifier profondément l’organisation territoriale et rapprocher certaines décisions du terrain, notamment via de nouvelles provinces, mais ne défend pas clairement un pouvoir normatif régional aussi large que celui décrit dans la question.",
      "Accord très fort : L’UDR articule son projet autour de la liberté, de la responsabilité, de l’autorité et de l’identité, avec une conception conservatrice de la cohésion nationale. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Accord très fort : L’UDR veut abolir le droit du sol et le regroupement familial, instaurer des quotas, réserver certaines prestations selon la durée de résidence et expulser les étrangers délinquants. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Désaccord net : L’UDR veut abolir le droit du sol et le regroupement familial, instaurer des quotas, réserver certaines prestations selon la durée de résidence et expulser les étrangers délinquants. Ils vont nettement à l’encontre de l’affirmation, même si tous les termes de la question ne sont pas rejetés explicitement.",
      "Désaccord fort : l’UDR revendique explicitement une préférence nationale et européenne pour certaines prestations ; la proposition d’égalité d’accès sans priorité fondée sur la nationalité est donc directement contraire à sa ligne.",
