      "Accord modéré : Le RN veut baisser plusieurs impôts et taxes pour les ménages et entreprises, supprimer l’IFI au profit d’un impôt sur la fortune financière et réduire les droits de succession pour les familles modestes et moyennes. Elle donne une orientation favorable, mais plus limitée, conditionnelle ou moins explicite que l’affirmation complète.",
      "Accord modéré : Le RN veut baisser plusieurs impôts et taxes pour les ménages et entreprises, supprimer l’IFI au profit d’un impôt sur la fortune financière et réduire les droits de succession pour les familles modestes et moyennes. Elle donne une orientation favorable, mais plus limitée, conditionnelle ou moins explicite que l’affirmation complète.",
