      "Désaccord net : le RN a rejeté le principe d’un plafond légal entre plus basse et plus haute rémunération, tout en reconnaissant certains excès et en préférant agir sur les bas salaires ou les indemnités exceptionnelles des dirigeants.",
      "Position intermédiaire : le RN privilégie surtout l'augmentation du salaire net par des baisses de cotisations et des exonérations plutôt qu'une hausse générale et significative du SMIC.",
      "Position intermédiaire : Le RN combine baisse d’impôts et soutien aux entreprises avec intervention publique, patriotisme économique, renationalisation des autoroutes et fonds souverain ; sa ligne n’est donc ni libérale pure ni étatiste pure. Ces éléments ne tranchent pas clairement l’arbitrage précis posé par la question, ce qui justifie une position intermédiaire.",
      "Accord net : Le RN combine baisse d’impôts et soutien aux entreprises avec intervention publique, patriotisme économique, renationalisation des autoroutes et fonds souverain ; sa ligne n’est donc ni libérale pure ni étatiste pure. Elle va nettement dans le sens de l’affirmation, sans établir nécessairement toutes les conditions ou tous les coûts formulés dans la question.",
      "Position intermédiaire : Le RN combine baisse d’impôts et soutien aux entreprises avec intervention publique, patriotisme économique, renationalisation des autoroutes et fonds souverain ; sa ligne n’est donc ni libérale pure ni étatiste pure. Ces éléments ne tranchent pas clairement l’arbitrage précis posé par la question, ce qui justifie une position intermédiaire.",
