      "Désaccord très fort : Le RN défend une souveraineté nationale forte, veut reprendre le contrôle de plusieurs politiques aujourd’hui européennes et refuse une évolution fédérale de l’Union. La position est directement ou presque entièrement opposée au sens de l’affirmation.",
      "Désaccord très fort : Le RN met l’accent sur l’identité, l’assimilation, l’autorité et la transmission, tout en revendiquant les libertés publiques et en contestant les dispositifs qu’il estime restreindre excessivement la liberté d’expression. La position est directement ou presque entièrement opposée au sens de l’affirmation.",
      "Accord modéré : Le RN veut stopper des fermetures d’hôpitaux et de maternités, renforcer les moyens de santé et soutenir les familles, tout en réduisant certaines structures administratives et en réservant davantage de dispositifs aux nationaux. Elle donne une orientation favorable, mais plus limitée, conditionnelle ou moins explicite que l’affirmation complète.",
      "Accord très fort : Le RN veut stopper des fermetures d’hôpitaux et de maternités, renforcer les moyens de santé et soutenir les familles, tout en réduisant certaines structures administratives et en réservant davantage de dispositifs aux nationaux. La position correspond directement ou presque entièrement au sens de l’affirmation.",
      "Position intermédiaire : Le RN met l’accent sur l’identité, l’assimilation, l’autorité et la transmission, tout en revendiquant les libertés publiques et en contestant les dispositifs qu’il estime restreindre excessivement la liberté d’expression. Ces éléments ne tranchent pas clairement l’arbitrage précis posé par la question, ce qui justifie une position intermédiaire.",
      "Réserve modérée : Le RN veut stopper des fermetures d’hôpitaux et de maternités, renforcer les moyens de santé et soutenir les familles, tout en réduisant certaines structures administratives et en réservant davantage de dispositifs aux nationaux. Ces éléments créent plutôt une réserve à l’égard de l’affirmation, sans constituer une opposition complète à tous ses termes."
