      "Accord très fort : Le programme d’Éric Zemmour défend une baisse marquée des impôts et charges sur les travailleurs et les entreprises, la réduction de la dépense publique et une politique favorable au travail, à l’industrie et à la propriété. La position correspond directement ou presque entièrement au sens de l’affirmation.",
